def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]
    r = n + 1

    recent_len = min(10, n)
    recent_c = 0
    for i in range(n - recent_len, n):
        if op[i] == 'C':
            recent_c += 1
    recent_ratio = recent_c / recent_len

    total_c = 0
    for a in op:
        if a == 'C':
            total_c += 1
    total_ratio = total_c / n

    if total_c == 0:
        return 'D'

    if n >= 12:
        after_c_total = 0
        after_c_coop = 0
        after_d_total = 0
        after_d_coop = 0
        for i in range(1, n):
            if me[i - 1] == 'C':
                after_c_total += 1
                if op[i] == 'C':
                    after_c_coop += 1
            else:
                after_d_total += 1
                if op[i] == 'C':
                    after_d_coop += 1

        if after_c_total >= 6 and after_d_total >= 6:
            if (after_d_coop / after_d_total) >= 0.75 and (after_c_coop / after_c_total) <= 0.30:
                return 'D'

    probe_fail = False
    completed = 0

    for p in range(5, n, 5):
        if me[p - 1] == 'D' and me[p] == 'C':
            if op[p] == 'D':
                probe_fail = True
                break
            if op[p - 1] == 'C' and op[p] == 'C':
                completed += 1

    exploit = (not probe_fail) and (completed >= 3) and (r >= 17)

    if me[-1] == 'D' and (r - 1) % 5 == 0 and r - 1 >= 5:
        if op[-1] == 'C' and not probe_fail and ((r - 1) <= 15 or exploit):
            return 'C'

    if r % 5 == 0 and r >= 5:
        scheduled = False
        if not probe_fail:
            if r <= 15:
                if completed >= (r // 5) - 1:
                    scheduled = True
            elif exploit:
                scheduled = True

        if scheduled:
            if exploit or r >= 20:
                if total_ratio >= 0.50 and recent_ratio >= 0.40 and op[-1] == 'C':
                    return 'D'
            else:
                if total_ratio >= 0.75 and recent_ratio >= 0.65 and op[-1] == 'C':
                    return 'D'

    if n == 1:
        return 'C' if op[0] == 'C' else 'D'

    if n >= 6:
        all_d = True
        all_c = True
        for i in range(n - 6, n):
            if op[i] == 'C':
                all_d = False
            else:
                all_c = False

        if all_d:
            if rng.random() < 0.08:
                return 'C'
            return 'D'

        if all_c:
            return 'C'

    if op[-1] == 'D' and me[-1] == 'C':
        if recent_ratio > 0.6:
            if rng.random() < 0.7:
                return 'C'
            return 'D'
        else:
            if rng.random() < 0.15:
                return 'C'
            return 'D'

    if op[-1] == 'D' and me[-1] == 'D':
        if r % 7 == 0 or recent_ratio > 0.35:
            return 'C'
        if rng.random() < 0.12:
            return 'C'
        return 'D'

    return 'C'
